import io
import pandas as pd

def load_closes(text):
    df = pd.read_csv(io.StringIO(text), index_col="date", parse_dates=True)
    df = df.sort_index()
    return df["close"].tolist()

import io
import pandas as pd

def clean_csv(text):
    df = pd.read_csv(io.StringIO(text), index_col="date", parse_dates=True)
    df = df.sort_index()
    return df[["close"]].to_csv(float_format="%.2f")

